function preprocess(source){const width=source.width||source.naturalWidth,height=source.height||source.naturalHeight,scale=Math.min(2,2400/width,Math.sqrt(6500000/(width*height)));const canvas=document.createElement('canvas');canvas.width=Math.round(width*scale);canvas.height=Math.round(height*scale);const context=canvas.getContext('2d',{willReadFrequently:true});context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(source,0,0,canvas.width,canvas.height);const image=context.getImageData(0,0,canvas.width,canvas.height);let total=0,count=0;for(let i=0;i<image.data.length;i+=64){total+=image.data[i]*.299+image.data[i+1]*.587+image.data[i+2]*.114;count++}const invert=total/count<125;for(let i=0;i<image.data.length;i+=4){let gray=image.data[i]*.299+image.data[i+1]*.587+image.data[i+2]*.114;if(invert)gray=255-gray;gray=gray<80?0:gray>190?255:gray;image.data[i]=image.data[i+1]=image.data[i+2]=gray;image.data[i+3]=255}context.putImageData(image,0,0);return canvas}
